(954, 'mail.canceled', '<p><br /><br />Hi <small>#name#</small>,</p>\n<p>We regret to inform you that your appointment for <small>#service_name#,</small>&nbsp; scheduled on <small>#date#</small> from <small>#start#</small> to <small>#end#</small> has been cancelled.</p>\n<p>If this is unexpected, please contact us to reschedule or for more information.</p>\n<p>Thank you,</p>\n<p>Expert Next Door</p>', 'default'),
(955, 'mail.confirmed', '<p>Hello <small>#name#,</small>,</p>\n<p>Thank you for booking with us!</p>\n<p>Your appointment for <small>#service_name#</small>is scheduled on <small>#date#</small> from <small>#start#</small> to <small>#end#</small> is confirmed.</p>\n<p>If you need to make changes, reply to this email or contact us.</p>\n<p>Status: <small>#status#</small></p>\n<p>Best regards,</p>\n<p>Expert Next Door</p>', 'default'),
(956, 'mail.admin', '<p>A new appointment has been booked:</p>\n<p>Name: <small>#name#</small><br />Email: <small>#email#</small><br />Phone: <small>#phone#</small></p>\n<p>Service: <small>#service_name#</small><br />Location: <small>#location_name#</small><br />Date: <small>#date#</small><br />Time: <small>#start#</small> &ndash; <small>#end#</small></p>\n<p>Price: <small>#price#</small></p>\n<p>Notes: <small>#description#</small></p>\n<p>Please review this booking in your WordPress dashboard.</p>', 'default'),
