(231, 'wpbdp_addons_l', 'a:3:{s:7:\"timeout\";i:1746786867;s:5:\"value\";s:61448:\"{\"1930\":{\"title\":\"Business Directory Combo Pack Module\",\"name\":\"Business Directory Combo Pack Module\",\"display_name\":\"Business Directory Combo Pack Module\",\"slug\":\"business-directory-combo-pack-module\",\"version\":\"\",\"new_version\":\"\",\"location\":[],\"excerpt\":\"\",\"id\":1930,\"released\":\"2014-07-03 22:34:10\",\"categories\":[],\"docs\":\"\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/business-directory-combo-pack-module\\/\",\"changelog\":\"\",\"plugin\":\"business-directory-combo-pack-module\\/business-directory-combo-pack-module.php\",\"icons\":{\"1x\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/icon-256x256.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1933\":{\"title\":\"PayFast Payment Module\",\"name\":\"PayFast Payment Module\",\"display_name\":\"PayFast Payment Module\",\"slug\":\"payfast-payment-module\",\"version\":\"5.0.3\",\"new_version\":\"5.0.3\",\"location\":[\"bdir\\/payfast\\/business-directory-payfast-5.0.3.zip\"],\"excerpt\":\"The module to help you increase revenue from your site by accepting payments on PayFast (South Africa)\",\"id\":1933,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Combo\",\"Elite\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/payfast-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/payfast-payment-module\\/\",\"changelog\":\"<h4>v5.0.3 - April 14, 2021<\\/h4>\\n<ul>\\n<li>Add support for coupon codes with subscriptions. Now the first payment can be a free trial.<\\/li>\\n<li>Update the plugin and author name.<\\/li>\\n<\\/ul>\\n<h4>v5.0.2 - January 2, 2018<\\/h4>\\n<p>PayFast 5.0.2<br \\/>\\n- Allow users to restart abandoned payments. (#3300)<\\/p>\\n<p>PayFast 5.0.1<br \\/>\\n- Update PayFast code for forcing ZAR currency. (#3165)<\\/p>\\n<p>PayFast 5.0<br \\/>\\n- Refactoring to use new premium module update mechanism<br \\/>\\n- Update to use with new payment workflow and fee handling<br \\/>\\n- Update for recurring payments<\\/p>\\n\",\"plugin\":\"business-directory-payfast\\/business-directory-payfast.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2014\\/09\\/PayFast-square.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1934\":{\"title\":\"Stripe Payment Module\",\"name\":\"Stripe Payment Module\",\"display_name\":\"Stripe Payment Module\",\"slug\":\"stripe-payment-module\",\"version\":\"5.5.1\",\"new_version\":\"5.5.1\",\"location\":[\"bdir\\/business-directory-stripe-5.5.1.zip\"],\"excerpt\":\"The module to help you increase revenue from your site by accepting payments using Stripe.\",\"id\":1934,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Combo\",\"Pro\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/stripe-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/stripe-payment-module\\/\",\"changelog\":\"<h4>v5.5.1 - November 25, 2024<\\/h4>\\n<ul>\\n<li>Fix: Issue with discounts not working with recurring payments<\\/li>\\n<li>Fix: Issue with checkout title not being applied<\\/li>\\n<\\/ul>\\n<h4>v5.5 - January 30, 2024<\\/h4>\\n<ul>\\n<li>New: Removed the Stripe custom form. Now all payments go through the Stripe checkout page for better reliability and increased conversion rates.<\\/li>\\n<li>Fix: Only use the Stripe customer ID if the user is logged in. This fixes an issue where the default user\'s customer ID could be used by others.<\\/li>\\n<li>Fix: Both 100% and partial coupon codes work much more reliably.<\\/li>\\n<li>Fix: Prevent conflicts with other plugins loading the Stripe library.<\\/li>\\n<li>Fix: Create a new session every time a payment is started to avoid sessions from getting mixed up.<\\/li>\\n<li>Fix: Better fallback when items are missing from the API response.<\\/li>\\n<li>New: Better PHP 8.2 compatibility.<\\/li>\\n<\\/ul>\\n<h4>v5.4 - April 5, 2023<\\/h4>\\n<ul>\\n<li>Adds PHP 8.0 support<\\/li>\\n<li>Updates the Stripe SDK to v10.1.0<\\/li>\\n<li>Sets a Stripe API version for better compatibility.<\\/li>\\n<li>New: Adds BYN currency.<\\/li>\\n<\\/ul>\\n<h4>v5.3 - August 18, 2022<\\/h4>\\n<ul>\\n<li>New: Update the Stripe API to v7.128.0<\\/li>\\n<li>If there\'s an error on checkout, switch the submit button back to \\\"pay now\\\"<\\/li>\\n<li>Add some field styling to the Stripe cc field<\\/li>\\n<li>Add a more helpful error message when subs are canceled<\\/li>\\n<li>Fix: On some sites, a JS error was showing on checkout of jQuery hadn\'t been loaded<\\/li>\\n<li>Fix: Don\'t send the renewal email with the first payment<\\/li>\\n<li>Use a consistent domain name for translation strings<\\/li>\\n<\\/ul>\\n<h4>v5.2 - March 15, 2021<\\/h4>\\n<ul>\\n<li>New: Include name and email when creating a customer in Stripe<\\/li>\\n<li>New: Add a link to the Stripe listing from the payment details.<\\/li>\\n<li>Updated Stripe SDK<\\/li>\\n<li>Remove BTC as payment method (no longer supported in Stripe).<\\/li>\\n<li>Match the checkout page styling in the custom form to the listing form.<\\/li>\\n<li>Hide Zip Code input from Stripe Card Element when Checkout Custom Form is used (use the input in form).<\\/li>\\n<li>Auto deactivate the plugin in PHP &lt; 5.6<\\/li>\\n<li>Fix: Validate Stripe Checkout Session.<\\/li>\\n<li>Fix: Validate module\'s Stripe configuration is available.<\\/li>\\n<li>Fix: The Stripe webhooks were failing, so payments were not getting auto marked as complete.<\\/li>\\n<li>Fix: Deleting a listing linked to a subscription resulted in a fatal error and subscription was not canceled<\\/li>\\n<li>Fix: If the notification for a payment comes through multiple times, don\'t extend the listing for each one.<\\/li>\\n<\\/ul>\\n\",\"plugin\":\"business-directory-stripe\\/business-directory-stripe.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2014\\/09\\/StripeLogo.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1935\":{\"title\":\"File Attachments Module\",\"name\":\"File Attachments Module\",\"display_name\":\"File Attachments Module\",\"slug\":\"file-attachments-module\",\"version\":\"5.1.4\",\"new_version\":\"5.1.4\",\"location\":[\"bdir\\/business-directory-attachments-5.1.4.zip\"],\"excerpt\":\"Allow for file attachments to listings--such as PDF, TXT, RTF and images\",\"id\":1935,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Basic\",\"Combo\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/file-uploads-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/file-attachments-module\\/\",\"changelog\":\"<h4>v5.1.4 - November 25, 2024<\\/h4>\\n<ul>\\n<li>New: Added the filesize to the add listing page<\\/li>\\n<li>Fix: A few PHP 8.2 notices<\\/li>\\n<\\/ul>\\n<h4>v5.1.3 - August 16, 2022<\\/h4>\\n<ul>\\n<li>Security fix: Check the file extension instead of only the file type<\\/li>\\n<li>Add better translation support for plugins like Loco translate<\\/li>\\n<li>Fix: On some sites, the attachment upload button was staying disabled in the listing submit process<\\/li>\\n<li>Update deprecated jQuery functions<\\/li>\\n<li>Update new naming for plans<\\/li>\\n<li>Big code cleanup<\\/li>\\n<\\/ul>\\n<h4>v5.1 - 5.1.2 - June 16, 2020<\\/h4>\\n<ul>\\n<li>5.1.2: Fix textdomain on some Attachments translatable texts. (#4577)<\\/li>\\n<li>5.1.1: Allow Attachment Header Text default value to be read by translation plugins when empty. (#4502)<\\/li>\\n<li>5.1: Add support for WP GDPR privacy hooks. (#3734)<\\/li>\\n<li>5.1: Add option to use attachment description as link text. (#3987)<\\/li>\\n<\\/ul>\\n\",\"plugin\":\"business-directory-attachments\\/business-directory-attachments.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/2013\\/03\\/pdf-e1410369882875.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1936\":{\"title\":\"ZIP Search Module\",\"name\":\"ZIP Search Module\",\"display_name\":\"ZIP Search Module\",\"slug\":\"zip-search-module\",\"version\":\"5.4.2\",\"new_version\":\"5.4.2\",\"location\":[\"bdir\\/zip\\/business-directory-zipcodesearch-5.4.2.zip\"],\"excerpt\":\"Add location-based listing search by radius (miles or km) from a postal\\/ZIP code. Works great with Regions + Maps\",\"id\":1936,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Combo\",\"Pro\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/zip-search-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/zip-search-module\\/\",\"changelog\":\"<h4>v5.5.1 - November 25, 2024<\\/h4>\\n<ul>\\n<li>Fix: Issue with discounts not working with recurring payments<\\/li>\\n<li>Fix: Issue with checkout title not being applied<\\/li>\\n<\\/ul>\\n<h4>v5.5 - January 30, 2024<\\/h4>\\n<ul>\\n<li>New: Removed the Stripe custom form. Now all payments go through the Stripe checkout page for better reliability and increased conversion rates.<\\/li>\\n<li>Fix: Only use the Stripe customer ID if the user is logged in. This fixes an issue where the default user\'s customer ID could be used by others.<\\/li>\\n<li>Fix: Both 100% and partial coupon codes work much more reliably.<\\/li>\\n<li>Fix: Prevent conflicts with other plugins loading the Stripe library.<\\/li>\\n<li>Fix: Create a new session every time a payment is started to avoid sessions from getting mixed up.<\\/li>\\n<li>Fix: Better fallback when items are missing from the API response.<\\/li>\\n<li>New: Better PHP 8.2 compatibility.<\\/li>\\n<\\/ul>\\n<h4>v5.4 - April 5, 2023<\\/h4>\\n<ul>\\n<li>Adds PHP 8.0 support<\\/li>\\n<li>Updates the Stripe SDK to v10.1.0<\\/li>\\n<li>Sets a Stripe API version for better compatibility.<\\/li>\\n<li>New: Adds BYN currency.<\\/li>\\n<\\/ul>\\n<h4>v5.3 - August 18, 2022<\\/h4>\\n<ul>\\n<li>New: Update the Stripe API to v7.128.0<\\/li>\\n<li>If there\'s an error on checkout, switch the submit button back to \\\"pay now\\\"<\\/li>\\n<li>Add some field styling to the Stripe cc field<\\/li>\\n<li>Add a more helpful error message when subs are canceled<\\/li>\\n<li>Fix: On some sites, a JS error was showing on checkout of jQuery hadn\'t been loaded<\\/li>\\n<li>Fix: Don\'t send the renewal email with the first payment<\\/li>\\n<li>Use a consistent domain name for translation strings<\\/li>\\n<\\/ul>\\n<h4>v5.2 - March 15, 2021<\\/h4>\\n<ul>\\n<li>New: Include name and email when creating a customer in Stripe<\\/li>\\n<li>New: Add a link to the Stripe listing from the payment details.<\\/li>\\n<li>Updated Stripe SDK<\\/li>\\n<li>Remove BTC as payment method (no longer supported in Stripe).<\\/li>\\n<li>Match the checkout page styling in the custom form to the listing form.<\\/li>\\n<li>Hide Zip Code input from Stripe Card Element when Checkout Custom Form is used (use the input in form).<\\/li>\\n<li>Auto deactivate the plugin in PHP &lt; 5.6<\\/li>\\n<li>Fix: Validate Stripe Checkout Session.<\\/li>\\n<li>Fix: Validate module\'s Stripe configuration is available.<\\/li>\\n<li>Fix: The Stripe webhooks were failing, so payments were not getting auto marked as complete.<\\/li>\\n<li>Fix: Deleting a listing linked to a subscription resulted in a fatal error and subscription was not canceled<\\/li>\\n<li>Fix: If the notification for a payment comes through multiple times, don\'t extend the listing for each one.<\\/li>\\n<\\/ul>\\n\",\"plugin\":\"business-directory-zipcodesearch\\/business-directory-zipcodesearch.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2014\\/09\\/zip_code_file_script-128.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1937\":{\"title\":\"Featured Levels Module\",\"name\":\"Featured Levels Module\",\"display_name\":\"Restrictions\",\"slug\":\"featured-levels-module\",\"version\":\"5.1\",\"new_version\":\"5.1\",\"location\":[\"bdir\\/levels\\/business-directory-featured-levels-5.1.zip\"],\"excerpt\":\"Make features like ratings, maps, form fields, images or character counts only available to certain listing plans.\",\"id\":1937,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Combo\",\"Elite\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/featured-levels-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/featured-levels-module\\/\",\"changelog\":\"<h4>v5.1 - April 6, 2022<\\/h4>\\n<ul>\\n<li>Add messages to notification center<\\/li>\\n<li>Update ui and colors for 6.0<\\/li>\\n<li>Change the plugin name to \\\"Restrictions\\\"<\\/li>\\n<li>Get rid of old featured levels code<\\/li>\\n<li>Update \\\"fee plan\\\" naming<\\/li>\\n<li>Change \\\"Manage Restrictions\\\" to \\\"Restrictions\\\"<\\/li>\\n<li>Add more sanitizing and escaping<\\/li>\\n<li>General code clean up and code styling<\\/li>\\n<\\/ul>\\n<h4>v5.0.9 - October 21, 2021<\\/h4>\\n<ul>\\n<li>Fix: Show all fee plans in fee settings regardless of free\\/paid status<\\/li>\\n<li>Update to remove calls to deprecated functions<\\/li>\\n<li>Update for PHP 8 compatibility<\\/li>\\n<\\/ul>\\n<h4>v5.0 - 5.0.8 - June 21, 2020<\\/h4>\\n<p>Featured Levels 5.0.8<br \\/>\\n* Use plan id to determine when maps section should be rendered on the frontend submit view. (#4542)<\\/p>\\n<p>Featured Levels 5.0.7<br \\/>\\n* Fix restrictions \'nofollow\' setting to work correctly when disabled. (#4467)<br \\/>\\n* Order field list for each fee in restrictions module. (#4433)<br \\/>\\n* Use \'Allow\' instead of \'Restrict\' in listing detail page setting in Featured Levels Module. (#4433)<\\/p>\\n<p>Featured Levels 5.0.6<br \\/>\\n* Validate listing plan exist before applying restrictions rules. (#4414, #4432)<\\/p>\\n<p>Featured Levels 5.0.5<br \\/>\\n* Use Multi-byte functions, if available, as string count on restrictions module. (#4305)<\\/p>\\n<p>Featured Levels 5.0.4<br \\/>\\n* Enhance Featured Levels character counter in both Frontend and Backend. (#4129)<\\/p>\\n<p>Featured Levels 5.0.3<br \\/>\\n* WYSIWYG character count fix for featured levels Module. (#3542)<br \\/>\\n* Update fee plans with empty capabilities. (#3721)<\\/p>\\n<p>Featured Levels 5.0.2<br \\/>\\n* Show all fee plans on the Restrictions screen. (#3257)<\\/p>\\n<p>Featured Levels 5.0.1<br \\/>\\n* Do not show information about content length if content field is disabled. (#3153)<\\/p>\\n<p>Featured Levels 5.0<br \\/>\\n* Refactoring to use new premium module update mechanism<br \\/>\\n* Update to use with new payment workflow and fee handling<br \\/>\\n* Refactoring to remove Featured Listings which confused everyone, simplified UI<\\/p>\\n\",\"plugin\":\"business-directory-featured-levels\\/business-directory-featured-levels.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/2013\\/03\\/tiered.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1938\":{\"title\":\"Regions Module\",\"name\":\"Regions Module\",\"display_name\":\"Regions Module\",\"slug\":\"regions-module\",\"version\":\"5.4.4\",\"new_version\":\"5.4.4\",\"location\":[\"bdir\\/business-directory-regions-5.4.4.zip\"],\"excerpt\":\"Allow location-based filtering of listings. Works great with ZIP search too!\",\"id\":1938,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Combo\",\"Pro\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/regions-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/regions-module\\/\",\"changelog\":\"<h4>v5.4.4 - November 11, 2024<\\/h4>\\n<ul>\\n<li>Fix: An issue with the permalinks rewrite that was breaking the site when &#091;business-directory-regions-browser] was added to the homepage<\\/li>\\n<li>Fix: Error in the search pages when numbers were used in the search value<\\/li>\\n<li>Fix: Compatibility errors with PHP 8.2<\\/li>\\n<li>Fix: A data type error in the API<\\/li>\\n<\\/ul>\\n<h4>v5.4.3 - July 12, 2023<\\/h4>\\n<ul>\\n<li>Fix: Fix fatal error \\\"Illegal offset type\\\" on activating the plugin when a certain setting is missing.<\\/li>\\n<\\/ul>\\n<h4>v5.4.2 - February 28, 2023<\\/h4>\\n<ul>\\n<li>Update: Better translation support.<\\/li>\\n<li>Fix: Clear Filter button was throwing an error.<\\/li>\\n<li>Fix: Resolve the PHP 8 errors.<\\/li>\\n<\\/ul>\\n<h4>v5.4.1 - April 11, 2022<\\/h4>\\n<ul>\\n<li>Fix submitting new region form<\\/li>\\n<li>Move admin menu lower<\\/li>\\n<li>Show autocomplete in the modal (not behind it)<\\/li>\\n<li>Fix clicking \\\"create default regions\\\"<\\/li>\\n<\\/ul>\\n<h4>v5.4 - April 7, 2022<\\/h4>\\n<ul>\\n<li>New: Add a way to get the region by slug in businessdirectory-region-subregions shortcode.<\\/li>\\n<li>Set new terms to enabled by default if no parent.<\\/li>\\n<li>Hide regions area if js present. This prevents page shifting.<\\/li>\\n<li>Add link to settings from Modules page.<\\/li>\\n<li>Updated for BD 6.0 compatibility.<\\/li>\\n<li>Move admin messages to 6.0 notification center.<\\/li>\\n<li>Remove form to add one region at a time, and use only the form that allows multiple regions at once.<\\/li>\\n<li>Security hardening.<\\/li>\\n<\\/ul>\\n\",\"plugin\":\"business-directory-regions\\/business-directory-regions.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/2012\\/12\\/regions-world.jpg\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1939\":{\"title\":\"Ratings Module\",\"name\":\"Ratings Module\",\"display_name\":\"Ratings Module\",\"slug\":\"ratings-module\",\"version\":\"5.3.2\",\"new_version\":\"5.3.2\",\"location\":[\"bdir\\/business-directory-ratings-5.3.2.zip\"],\"excerpt\":\"Collect social proof with Ratings on businesses. Let your users express their opinion of listed businesses.\",\"id\":1939,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Basic\",\"Combo\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/ratings-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/ratings-module\\/\",\"changelog\":\"<h4>v5.3.1 - November 25, 2024<\\/h4>\\n<ul>\\n<li>Fix: Improve star image styling<\\/li>\\n<li>Fix: PHP 8.2 error notices<\\/li>\\n<\\/ul>\\n<h4>v5.3 - September 11, 2023<\\/h4>\\n<ul>\\n<li>New: Add a searchable table to show all ratings in the admin area.<\\/li>\\n<li>New: Replace the rating dropdown with selectable stars in the advanced search<\\/li>\\n<li>New: Remove the \\\"enable ratings\\\" setting since it wasn\'t working everywhere. The plugin should be disabled instead.<\\/li>\\n<li>New: Remove the \\\"Require email to unregistered users for posting reviews?\\\" setting since it was confusing. Now an email field will be included for logged out users by default. Use the \'wpbdp_listing_require_email\' hook to remove the email field.<\\/li>\\n<li>When listings are sorted by rating, show listings higher if they have more reviews with the same average rating<\\/li>\\n<li>Improve database query speed with an index<\\/li>\\n<li>Better translation support with Locotranslate.<\\/li>\\n<li>Add an icon in the admin settings<\\/li>\\n<li>Fix: There was an error in the ratings schema for Google<\\/li>\\n<li>Fix: If there is a custom login url set in the BD settings, use it in the login link before leaving a review.<\\/li>\\n<li>Fix: The save button no longer returns an error message when editing a review in the admin area without making a change.<\\/li>\\n<li>Fix: In some BD themes, the \\\"leave a review\\\" button wasn\'t showing the review form.<\\/li>\\n<li>Fix: Make the review form layout and spacing match the other BD forms on the page<\\/li>\\n<li>Fix: When a listing showed a half star, one half was the wrong color<\\/li>\\n<\\/ul>\\n<h4>vv5.2.1 - January 14, 2022<\\/h4>\\n<ul>\\n<li>New: Add support for emojis in the rating comment<\\/li>\\n<li>Fix: Admin ratings review page issue where ratings were not showing properly<\\/li>\\n<li>Fix: Admin add new rating in admin edit listing page<\\/li>\\n<li>Fix: Conflict with WooCommerce showing multiple ratings<\\/li>\\n<li>Fix: PHP 8 support<\\/li>\\n<\\/ul>\\n<h4>v5.2 - December 3, 2020<\\/h4>\\n<ul>\\n<li>Update the stars for style and accessibility<\\/li>\\n<li>Cut down on overhead by replacing images with svg, exclude the javascript, and minimal css<\\/li>\\n<li>Combine the separate admin and front end javascripts<\\/li>\\n<li>Match the form styling to the listing form<\\/li>\\n<li>Remove tooltip settings since the radio numbers are accessible now<\\/li>\\n<li>Fixes for security issues<\\/li>\\n<li>Hide the ratings field setting to hide for admins in the listing form since it\'s always hidden.<\\/li>\\n<li>Requires Business Directory 5.8+<\\/li>\\n<\\/ul>\\n<h4>v5.0 - 5.1.5 - June 15, 2020<\\/h4>\\n<p>Ratings 5.1.5 (skipped .1.4)<br \\/>\\n- Add reviewer email to Listing ratings pending review table. (#4557)<\\/p>\\n<p>Ratings 5.1.3<br \\/>\\n- Add ratings (average) and rating count as sortable fields for listings. (#4269)<\\/p>\\n<p>Ratings 5.1.2<br \\/>\\n- Prevent Ratings as default sorting in advanced search. (#4211)<\\/p>\\n<p>Ratings 5.1.1<br \\/>\\n- Remove multiple Rating posting restriction for admin users.<br \\/>\\n- Show \\\"Add Rating\\\" link after posting a rating in dashboard. (#4164)<br \\/>\\n- Fix ratings sorting in all BD views. (#4168)<\\/p>\\n<p>Ratings 5.1<br \\/>\\n\\u2013 Add support for WP GDPR privacy hooks. (#3734)<\\/p>\\n<p>Ratings 5.0.6<br \\/>\\n\\u2013 Prevent ratings form layout break in Gutenberg. (#3897)<br \\/>\\n\\u2013 Remove get_client_ip_address() method from BusinessDirectory_RatingsModule to use wpbdp_get_client_ip_address() BD core function instead.<br \\/>\\n\\u2013 Update core plugin required version for ratings module to 5.3.4.<\\/p>\\n<p>Ratings 5.0.5<br \\/>\\n- Add \'Ratings\' to listings sort options setting. (#3879)<\\/p>\\n<p>Ratings 5.0.4<br \\/>\\n- Update Ratings Module Readme links to knowledge-base. (#3390)<br \\/>\\n- Fix links where target=\\\"_blank\\\" as security issue. (#3597)<br \\/>\\n- Require email address when user is posting rating. (#3614)<br \\/>\\n- Allow admins view entire review before approving. (#3623)<\\/p>\\n<p>Ratings 5.0.3<br \\/>\\n- Do not shows the \'Rate\' link when restrictions don\'t allow public to rate. (#3395)<\\/p>\\n<p>Ratings 5.0.2<br \\/>\\n- Disallow listing owner from rating their own listing. (#2807)<\\/p>\\n<p>Ratings 5.0.1<br \\/>\\n- Make \'Post Your Review\' form visible on all devices. (#3302)<\\/p>\\n<p>Ratings 5.0<br \\/>\\n- Refactoring to use new premium module update mechanism<br \\/>\\n- Update to use with new payment workflow and fee handling<\\/p>\\n\",\"plugin\":\"business-directory-ratings\\/business-directory-ratings.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2014\\/09\\/Ratings-square.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1940\":{\"title\":\"Google Maps Module\",\"name\":\"Google Maps Module\",\"display_name\":\"Google Maps Module\",\"slug\":\"google-maps-module\",\"version\":\"5.2.2\",\"new_version\":\"5.2.2\",\"location\":[\"bdir\\/google-maps\\/business-directory-googlemaps-5.2.2.zip\"],\"excerpt\":\"This module allows your listings to display a Google Map for their address, show search results on a map and the overall directory on a map.\",\"id\":1940,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Combo\",\"Pro\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/google-maps-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/google-maps-module\\/\",\"changelog\":\"<h4>v5.2.2 - May 11, 2022<\\/h4>\\n<ul>\\n<li>Remove restricted API key notices since restrictions are encouraged.<\\/li>\\n<li>Load map js in footer.<\\/li>\\n<li>Add settings link on modules page.<\\/li>\\n<li>Use correct link to settings page in error messages for 6.0.<\\/li>\\n<li>Remove old error messages so it doesn\'t end up with a large build-up of messages that don\'t apply.<\\/li>\\n<li>Show error messages on any Bd settings page, instead of only on map settings.<\\/li>\\n<li>Use 6.0 notification center for error messages.<\\/li>\\n<li>Simplify the error messages to make them more readable.<\\/li>\\n<\\/ul>\\n<h4>v5.2.1 - March 31, 2021<\\/h4>\\n<ul>\\n<li>New: If map should show on listings pages, show on regions pages too<\\/li>\\n<li>New: Use extra atts in the locations array to customize markers<br \\/>\\nExample:<\\/p>\\n<p>add_filter( \'wpbdp_googlemaps_map_locations\', \'function_here\' );<br \\/>\\nfunction function_here( $locations ) {<br \\/>\\nforeach ( $locations as $k =&gt; $l ) {<br \\/>\\n$locations[ $k ][\'icon\'] = \'https:\\/\\/developers.google.com\\/maps\\/documentation\\/javascript\\/examples\\/full\\/images\\/beachflag.png\';<br \\/>\\n}<br \\/>\\nreturn $locations;<br \\/>\\n}\\n<\\/li>\\n<li>Fix: Added support for PHP 8<\\/li>\\n<\\/ul>\\n<h4>v5.2 - February 3, 2021<\\/h4>\\n<ul>\\n<li>New: Added a setting to customize the tooltip content.<\\/li>\\n<li>New: Added a bunch of hooks. wpbdp_address_format allows the content in the tooltip to change with extra fields or reorder the address fields. wpbdp_map_id allows the settings in the Google maps api area to be used in the maps. wpbdp_map_markers can set a custom location for cluster map markers.<\\/li>\\n<li>Removed the checkbox to enable maps (if that was unchecked before, the plugin will be deactivated).<\\/li>\\n<li>Updated the cluster and Spiderfy scripts (Spiderfy shows both listings if they are stacked)<\\/li>\\n<li>If there\'s a javascript error message, it will be saved and shown in the admin area. (ie enable billing)<\\/li>\\n<li>Fix: When zoomed in on multiple markers with the same address, Spiderfy takes over instead of showing a cluster marker that doesn\'t do anything<\\/li>\\n<li>Fix: Remove reference to the deprecated debug setting (gets rid of the warning message)<\\/li>\\n<\\/ul>\\n<h4>v5.0 - 5.1.8 - June 16, 2020<\\/h4>\\n<p>Google Maps 5.1.8<br \\/>\\n- Adjust manual listing location on listing edit view. (#4531)<br \\/>\\n- Use plan id to fix module integration with Featured Levels module. (#4542)<\\/p>\\n<p>Google Maps 5.1.7<br \\/>\\n- Prevent listing location override is lost when loading edit view. (#4531)<br \\/>\\n- Remove default business markers from directory and listing maps. (#4531, #4533)<\\/p>\\n<p>Google Maps 5.1.6<br \\/>\\n- Update maps markers information when using Marker Clusterer. (#4450, #4453)<\\/p>\\n<p>Google Maps 5.1.5<br \\/>\\n- New Feature: Include Marker Clusterer indicators to display listings on map. (#4386)<\\/p>\\n<p>Google Maps 5.1.4<br \\/>\\n- Fix location override section display on submit\\/edit views. (#4254)<\\/p>\\n<p>Google Maps 5.1.3<br \\/>\\n- Prevent google maps module script enqueuing modifications when on admin panel. (#4202)<\\/p>\\n<p>Google Maps 5.1.2<br \\/>\\n- Validate frontend view before changing maps scripts (#4143)<\\/p>\\n<p>Google Maps 5.1.1<br \\/>\\n- Prevent google maps BD script breaks src url for non-BD pages. (#4125)<\\/p>\\n<p>Google Maps 5.1<br \\/>\\n- Enhance listing manual listing location behavior to use user input for initial location. (#3995)<\\/p>\\n<p>Google Maps 5.0.10<br \\/>\\n- Improve map display before listings. (#3849)<br \\/>\\n- Update workaround to enqueue Google Maps API once. (#3865)<br \\/>\\n- Update google maps request-denied notice.<\\/p>\\n<p>Google Maps 5.0.8<br \\/>\\n- Increase priority to execute listing geolocation update after listing is completely saved in dashboard. (#3746)<\\/p>\\n<p>Google Maps 5.0.7<br \\/>\\n- Fix Fatal Error on PHP 7.2 (#3609)<\\/p>\\n<p>Google Maps 5.0.6<br \\/>\\n- Fix directions map not rendering properly. (#3591)<br \\/>\\n- Fix Google Maps to work with JS API version 3.32. (#3591)<\\/p>\\n<p>Google Maps 5.0.5<br \\/>\\n- Downgraded to older version of the Google Maps API because their latest one broke without warning on Feb 28<\\/p>\\n<p>Google Maps 5.0.4<br \\/>\\n- Allow admins to define a default location for the Location Chooser. (#3519)<br \\/>\\n- Google Maps: Update layout for Driving Directions. (#3516)<\\/p>\\n<p>Google Maps 5.0.3<br \\/>\\n- Attempt to get directions on Safari. (#3393)<\\/p>\\n<p>Google Maps 5.0.2<br \\/>\\n- Restore Place Chooser feature to Submit Listing view. (#3397)<br \\/>\\n- Fix typo in googlemaps-size option to make map custom size works properly. (#3415)<\\/p>\\n<p>Google Maps 5.0.1<br \\/>\\n- Automatically strip leading and trailing spaces when the value for the Google Maps API key setting is saved. (#3336)<\\/p>\\n<p>Google Maps 5.0<br \\/>\\n- Refactoring to use new premium module update mechanism<br \\/>\\n- Update to use with new payment workflow and fee handling<\\/p>\\n\",\"plugin\":\"business-directory-googlemaps\\/business-directory-googlemaps.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/2012\\/07\\/googleplaces-icon.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"1942\":{\"title\":\"PayPal Gateway Module\",\"name\":\"PayPal Gateway Module\",\"display_name\":\"PayPal Gateway Module\",\"slug\":\"paypal-gateway-module\",\"version\":\"5.0.6\",\"new_version\":\"5.0.6\",\"location\":[\"bdir\\/business-directory-paypal-5.0.6.zip\"],\"excerpt\":\"The module to help you increase revenue from your site by accepting payments via PayPal.\",\"id\":1942,\"released\":\"2014-07-03 00:00:00\",\"categories\":[\"Basic\",\"Combo\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/paypal-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/paypal-gateway-module\\/\",\"changelog\":\"<h4>v5.0.6 - January 30, 2023<\\/h4>\\n<ul>\\n<li>New: Include a link to the PayPal payment with the ID on the payment history page.<\\/li>\\n<li>Update: Better translation support.<\\/li>\\n<li>Fix: Resolve the PHP 8 error with renewal payments.<\\/li>\\n<\\/ul>\\n<h4>v5.0.5 - April 14, 2021<\\/h4>\\n<ul>\\n<li>Fix: Update the 404 link to IPN instructions<\\/li>\\n<\\/ul>\\n<h4>v5.0.4 - November 6, 2018<\\/h4>\\n<p>PayPal 5.0.4<br \\/>\\n\\u2013 Include PayPal in AED not supported gateways warning.<\\/p>\\n<p>PayPal 5.0.3<br \\/>\\n- Update code used to verify PayPal IPNs. (#3354)<br \\/>\\n- Add credit cards logos for PayPal. (#3317)<\\/p>\\n<p>PayPal 5.0.2<br \\/>\\n- Update code used to verify PayPal IPNs. (#3300)<br \\/>\\n- Allow users to restart abandoned payments. (#3300)<\\/p>\\n<p>PayPal 5.0.1<br \\/>\\n- Do not auto-publish recurring listings on notification of the first payment received. (#3244)<\\/p>\\n<p>PayPal 5.0<br \\/>\\n- Refactoring to use new premium module update mechanism<br \\/>\\n- Update to use with new payment workflow and fee handling<\\/p>\\n\",\"plugin\":\"business-directory-paypal\\/business-directory-paypal.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/2012\\/01\\/Paypal_icon.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"5761\":{\"title\":\"Claim Listings Module\",\"name\":\"Claim Listings Module\",\"display_name\":\"Claim Listings Module\",\"slug\":\"claim-listings-module\",\"version\":\"5.4.1\",\"new_version\":\"5.4.1\",\"location\":[\"bdir\\/business-directory-claim-listings-5.4.1.zip\"],\"excerpt\":\"Allows businesses to claim existing listings on your site, just like Yelp or Foursquare!  Great way to build immediate revenue.\",\"id\":5761,\"released\":\"2015-01-07 00:00:00\",\"categories\":[\"Combo\",\"Elite\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/claim-listings-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/claim-listings-module\\/\",\"changelog\":\"<p><h4>v5.4.1 - November 25, 2024<\\/h4>\\n<ul>\\n<li>New: Added an admin notice that\'s shown if the user is trying to claim a listing from the account that\'s assigned as the unclaimed user ID<\\/li>\\n<li>Fix: A few PHP notices that were shown when using PHP 8.2 or above<\\/li>\\n<\\/ul>\\n<h4>v5.4 - November 29, 2023<\\/h4>\\n<ul>\\n<li>New: Add a withdrawn claim is set to withdrawn instead of rejected.<\\/li>\\n<li>New: Send a reminder email 3 days after waiting payment<\\/li>\\n<li>New: Show the claim button on a listing if user has a pending claim so they can see the next step. This includes a link to pay for approved claims when viewing the listing<\\/li>\\n<li>New: During claim process, take the user directly to the payment page if approval is not required<\\/li>\\n<li>New: Add reject link on approved claims and approve link on rejected claims in case of mistakes<\\/li>\\n<li>New: The button on checkout page is now styled as a button<\\/li>\\n<li>New: Show the expire date in claims table when pending so it\'s easy to see when it will expire<\\/li>\\n<li>Update: Set the status on the listing page to \'Pending Claim Payment\' instead of showing \'Pending\' even after admin approved<\\/li>\\n<li>Update: Set the default release claim time to 30 days (It was 5 days)<\\/li>\\n<li>Fix: Claims were not getting automatically getting released after the set amount of time. <\\/li>\\n<li>Fix: Clicking the claim button wasn\'t scrolling to the claim form in all BD themes<\\/li>\\n<li>Fix: a username for the default unclaimed user wasn\'t consistently counting as unclaimed<\\/li>\\n<li>Fix: Don\'t count a free variable price plan as paid for immediate completed claim without extra user action more often<\\/li>\\n<li>Fix: if there are multiple claims on the same listing use the most recent to check the status<\\/li>\\n<li>Update: Clean up the settings pages and show some settings conditionally to simplify.<\\/li>\\n<\\/ul>\\n<h4>v5.3.1 - July 19, 2022<\\/h4>\\n<ul>\\n<li>Correctly load translation files for better integration with plugins like Loco translate<\\/li>\\n<li>Removed the \\\"enable claim listings\\\" checkbox. Plugin will be disabled if this box was checked<\\/li>\\n<li>Only load the admin end javascript on BD admin pages<\\/li>\\n<li>Fix: The default email message with payment included \\\"nn\\\"<\\/li>\\n<li>Fix: When used with a tabbed theme, automatically switch tabs when the \\\"Claim Listing\\\" button is clicked<\\/li>\\n<li>Fix: With some settings, the login form to claim a listing required a page refresh in order to see the claim form<\\/li>\\n<\\/ul>\\n<h4>vv5.3 - March 7, 2022<\\/h4>\\n<ul>\\n<li>Fix: Frontend claim button appearance for non-admins<\\/li>\\n<li>Fix : Claim status label on admin side<\\/li>\\n<li>Fix : Bulk action unclaim<\\/li>\\n<li>Fix : Claim button styling on frontend for consistency<\\/li>\\n<\\/ul>\\n<h4>v5.2.9 - January 4, 2022<\\/h4>\\n<ul>\\n<li>Enhancement : Add default rejection reason when no reason is added by the admin. Default reason will be \\\"None\\\"<\\/li>\\n<li>Fix : Delete pending unpaid payments belong to the claim when a claim is deleted<\\/li>\\n<li>Security enhancements<\\/li>\\n<li>PHP 8 updates<\\/li>\\n<\\/ul>\\n\",\"plugin\":\"business-directory-claim-listings\\/business-directory-claim-listings.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2014\\/12\\/ClaimListing.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"24162\":{\"title\":\"Discount Codes Module\",\"name\":\"Discount Codes Module\",\"display_name\":\"Discount Codes Module\",\"slug\":\"discount-codes-module\",\"version\":\"5.0.4\",\"new_version\":\"5.0.4\",\"location\":[\"bdir\\/business-directory-discount-codes-5.0.4.zip\"],\"excerpt\":\"Offer discount codes for listings, in percent or fixed amount.  Limit to certain users or total redemptions.\",\"id\":24162,\"released\":\"2015-07-21 00:00:00\",\"categories\":[\"Combo\",\"Pro\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/knowledge-base\\/discount-codes-module\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/discount-codes-module\\/\",\"changelog\":\"<h4>v5.0.4 - November 11, 2024<\\/h4>\\n<ul>\\n<li>New: Added a notice for the user when the coupon code cannot be applied<\\/li>\\n<li>Fix: Fixed a couple of compatibility issues with PHP 8<\\/li>\\n<li>Fix: Prevented PHP notices if coupon code description was left empty<\\/li>\\n<\\/ul>\\n<h4>v5.0.3 - July 12, 2023<\\/h4>\\n<ul>\\n<li>Fix: Some translation strings weren\'t showing up in Loco translate.<\\/li>\\n<li>Fix: Correctly apply discount codes when using the custom form option with Stripe checkout.<\\/li>\\n<\\/ul>\\n<h4>vv5.0.2 - March 9, 2022<\\/h4>\\n<ul>\\n<li>Improvement : loading and saving coupon data securely on admin side<\\/li>\\n<li>Fix : PHP 8 compatibility<\\/li>\\n<\\/ul>\\n<h4>v5.0.1 - August 22, 2018<\\/h4>\\n<p>v5.0.1<\\/p>\\n<ul>\\n<li>Use plugin\\/module version to register scripts and styles. (#3363)<\\/li>\\n<\\/ul>\\n<p>v5.0<\\/p>\\n<ul>\\n<li>Refactoring to use new premium module update mechanism<\\/li>\\n<li>Update to use with new payment workflow and fee handling<\\/li>\\n<\\/ul>\\n\",\"plugin\":\"business-directory-discount-codes\\/business-directory-discount-codes.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2015\\/07\\/discount-code.png\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"40919\":{\"title\":\"Business Card Theme\",\"name\":\"Business Card Theme\",\"display_name\":\"Business Card Theme\",\"slug\":\"business-card-theme\",\"version\":\"1.3\",\"new_version\":\"1.3\",\"location\":[\"bdir\\/themes\\/business-card\\/business-card-1.3.zip\"],\"excerpt\":\"A theme to display listings very similar to business cards on both list and detail views. Go digital with this WordPress business card template!\",\"id\":40919,\"released\":\"2016-01-13 00:00:00\",\"categories\":[\"Elite\",\"Theme\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/business-card-theme\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/business-card-theme\\/\",\"changelog\":\"<h4>vv1.3 - January 17, 2022<\\/h4>\\n<ul>\\n<li>Enhancement: Standardize template files for better forward compatibility<\\/li>\\n<li>Enhancement: Update styling and allow more elements to adapt from WordPress theme so it\'ll match better<\\/li>\\n<li>Fix: Prevent single listing from scrolling automatically on load<\\/li>\\n<li>Enhancement: PHP 8 improvements<\\/li>\\n<\\/ul>\\n<h4>v1.2 - 1.2.5 - June 16, 2020<\\/h4>\\n<p>Version 1.2.5<br \\/>\\n* Exclude Address 2 field from excerpt and single content templates in Business Card Theme. (#4588)<\\/p>\\n<p>Version 1.2.4<br \\/>\\n* Integrate \'rate this listing\' link with Business Card theme. (#4507)<br \\/>\\n* Remove duplicated blocks.<br \\/>\\n* Fix sticky badge layout. (#4507)<\\/p>\\n<p>Version 1.2.3<br \\/>\\n* Fix excerpt title for restricted access plans. (#4501)<\\/p>\\n<p>Version 1.2.2<br \\/>\\n* Include \\\"return to\\\" button to go back to search, category and tag views. (#3349)<br \\/>\\n* Fix social fields layout. (#4020)<\\/p>\\n<p>Version 1.2.1<br \\/>\\n* Fix Theme compatibility with Twenty Nineteen default Theme (WP 5.0).<\\/p>\\n<p>Version 1.2<br \\/>\\n* Avoid repeating address fields in the single view. (#2839)<br \\/>\\n* Add support for responsive behavior in maps with directions. (#2875)<\\/p>\\n\",\"plugin\":\"business-card\\/theme.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2016\\/04\\/businesscard.jpg\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"40920\":{\"title\":\"Elegant Business Theme\",\"name\":\"Elegant Business Theme\",\"display_name\":\"Elegant Business Theme\",\"slug\":\"elegant-business-theme\",\"version\":\"1.1.15\",\"new_version\":\"1.1.15\",\"location\":[\"bdir\\/themes\\/elegant-business\\/elegant-business-1115.zip\"],\"excerpt\":\"Do you need a professional listing website template for WordPress? Get this one! It\\u2019s a stylish theme for a modern directory with some flair.\",\"id\":40920,\"released\":\"2016-01-13 00:00:00\",\"categories\":[\"Elite\",\"Theme\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/elegant-business-theme\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/elegant-business-theme\\/\",\"changelog\":\"<p>Version 1.1.15<br \\/>\\n* Exclude Address 2 field from excerpt and single content templates in Elegant Business Theme. (#4588)<\\/p>\\n<p>Version 1.1.14<br \\/>\\n* Fix excerpt title for restricted access plans. (#4501)<\\/p>\\n<p>Version 1.1.13<br \\/>\\n* Add missing space on Elegant Business excerpt_content template. (#4448)<\\/p>\\n<p>Version 1.1.11<br \\/>\\n* Add sticky badge to excerpt view. (#4381)<br \\/>\\n* Add missing translation in excerpt_content template.<br \\/>\\n* Update default layout styling.<\\/p>\\n<p>Version 1.1.10<br \\/>\\n- Include \\\"return to\\\" button to go back to search, category and tag views. (#3349)<br \\/>\\n- Fix social fields layout. (#4020)<\\/p>\\n<p>Version 1.1.9<br \\/>\\n\\u2013 Update Plugin and Themes single_content templates to use default picture. (#3825)<br \\/>\\n\\u2013 Prevent Elegant Business theme stacking on default themes. (#3962)<br \\/>\\n\\u2013 Fix Theme compatibility with Twenty Nineteen default Theme (WP 5.0).<\\/p>\\n<p>Version 1.1.8<br \\/>\\n- Correct spacing between fields. (#2978)<\\/p>\\n<p>Version 1.1.7<br \\/>\\n- Add support for responsive behavior in maps with directions. (#2875)<\\/p>\\n<p>Version 1.1.4<br \\/>\\n- Add German translation.<br \\/>\\n- Add Swedish translation.<\\/p>\\n<p>Version 1.1.2<br \\/>\\n- Allow admins to disable the CSS rules for listing action buttons. (#2468)<br \\/>\\n- Add \\\"country\\\" as a new theme tag. (#2538)<\\/p>\\n<p>Version 1.1.1<br \\/>\\n- Fix theme CSS to work when CPT integration is disabled. (#2492)<\\/p>\\n<p>Version 1.1<br \\/>\\n- Add support for translations. (#2183)<br \\/>\\n- Improve appearance of list of listings and single listing views in mobile devices. (#2396)<\\/p>\\n<p>Version 1.0.11<br \\/>\\n- Improve appearance of list of listings and single listing views in mobile devices. (#2396)<\\/p>\\n<p>Version 1.0.10<br \\/>\\n- Added support for translation file in theme<\\/p>\\n<p>Version 1.0.9<br \\/>\\n- Minor CSS fix. (#2177)<\\/p>\\n<p>Version 1.0.8<br \\/>\\n- Add more detailed styles to prevent jquery-ui themes from overriding ours. (#2139)<\\/p>\\n<p>Version 1.0.7<br \\/>\\n- Added support for City and State to tag in the theme for display<\\/p>\\n<p>Version 1.0.6<br \\/>\\n- Fixed display bug where Address field showed in the wrong place<\\/p>\\n<p>Version 1.0.5<br \\/>\\n- Minor CSS updates and bug fixes for final BD core 4.0 release<\\/p>\\n<p>Version 1.0.4<br \\/>\\n- Final prep for theme release<\\/p>\\n<p>Version 1.0.3<br \\/>\\n- Field placement fixes, minor UI corrections, field display options<\\/p>\\n<p>Version 1.0.2<br \\/>\\n- Map placement fix<br \\/>\\n- Contact settings fix to honor global settings<\\/p>\\n<p>Version 1.0.1<br \\/>\\n- Fixed theme updates<br \\/>\\n- Various CSS changes to adjust spacing<br \\/>\\n- Image size recommendations for theme<br \\/>\\n- Field tag adjustments to improve onboarding when doing first time setup<\\/p>\\n<p>Version 1.0<br \\/>\\n- Initial release<\\/p>\\n\",\"plugin\":\"elegant-business\\/theme.php\",\"icons\":{\"1x\":\"https:\\/\\/businessdirectoryplugin.com\\/wp-content\\/uploads\\/edd\\/2016\\/04\\/elegant.jpg\"},\"banners\":{\"high\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\",\"low\":\"https:\\/\\/ps.w.org\\/business-directory-plugin\\/assets\\/banner-1544x500.png\"},\"search_terms\":\"\",\"is_new\":false},\"40925\":{\"title\":\"Mobile Compact Theme\",\"name\":\"Mobile Compact Theme\",\"display_name\":\"Mobile Compact Theme\",\"slug\":\"mobile-compact-theme\",\"version\":\"1.1.3\",\"new_version\":\"1.1.3\",\"location\":[\"bdir\\/themes\\/mobile-compact\\/mobile-compact-113.zip\"],\"excerpt\":\"The best WordPress directory theme for mobile-first listing sites. Perfect if your site is mainly accessed on phones with tight icons & displays.\",\"id\":40925,\"released\":\"2016-01-13 00:00:00\",\"categories\":[\"Elite\",\"Theme\"],\"docs\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/mobile-compact-theme\\/\",\"link\":\"https:\\/\\/businessdirectoryplugin.com\\/downloads\\/mobile-compact-theme\\/\",\"changelog\":\"<p>Version 1.1.3<br \\/>\\n- Include \\\"return to\\\" button to go back to search, category and tag views. (#3349)<br \\/>\\n- Fix social fields layout. (#4020)<\\/p>\\n<p>Version 1.1.2<br \\/>\\n\\u2013 Update Plugin and Themes single_content templates to use default picture. (#3825)<\\/p>\\n<p>Version 1.1.1<br \\/>\\n- Add support for responsive behavior in maps with directions. (#2875)<\\/p>\\n<p>Version 1.1<br \\/>\\n- Add support for translations. (#2183)<\\/p>\\n<p>Version 1.0.7<br \\/>\\n- Added support for translation file in theme<\\/p>\\n<p>Version 1.0.6<br \\/>\\n- Fixed display bug where Address field showed in the wrong place<\\/p>\\n<p>Version 1.0.5<br \\/>\\n- Minor CSS updates and bug fixes for final BD core 4.0 release<\\/p>\\n<p>Version 1.0.4<br \\/>\\n- Final prep for theme release<\\/p>\\n<p>Version 1.0.3<br \\/>\\n- Field placement fixes, minor UI corrections, field display options<\\/p>\\n<p>Version 1.0.2<br \\/>\\n- Map placement fix<br \\/>\\n- Contact settings fix to honor global settings<\\/p>\\n<p>Version 1.0.1<br \\/>\\n- Fixed theme updates<br \\/>\\n- Various CSS changes to adjust spacing<br \\/>\\n- Image size recommendations